def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals (start, end).

    - Discards empty intervals (start == end).
    - Raises ValueError if start > end.
    - Returns a new list of sorted tuples; input is not mutated.
    """
    valid = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"interval start {start} > end {end}")
        if start != end:
            valid.append((start, end))

    valid.sort(key=lambda t: (t[0], t[1]))

    merged = []
    for start, end in valid:
        if merged and start <= merged[-1][1]:
            prev_start, prev_end = merged[-1]
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))

    return merged
```

