def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Raises ValueError if path is not absolute (doesn't start with '/').
    - Collapses repeated slashes.
    - Removes '.' components.
    - Resolves '..' components without going above root.
    - Returns '/' for the root path.
    - Never returns a trailing slash for non-root paths.
    """
    if not path.startswith('/'):
        raise ValueError(f"Path must be absolute, got: {path!r}")

    stack: list[str] = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack) if stack else '/'
```

