def pack(items, max_bytes):
    if not items:
        return []
    result = []
    current = []
    current_size = 0
    for item in items:
        byte_len = len(item.encode('utf-8'))
        if byte_len > max_bytes:
            raise ValueError(
                f"Item {item!r} is {byte_len} bytes, exceeds max_bytes={max_bytes}"
            )
        if current and current_size + byte_len > max_bytes:
            result.append(current)
            current = []
            current_size = 0
        current.append(item)
        current_size += byte_len
    if current:
        result.append(current)
    return result
