import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a new independent dict.

    - Overlay values replace base values for non-dict types (lists, scalars, None).
    - Both-dict values are merged recursively.
    - None in overlay does not delete the key; it sets the value to None.
    - Neither input is mutated, and no nested references are shared with the result.
    """
    result = {}
    all_keys = set(base) | set(overlay)
    for key in all_keys:
        if key in base and key in overlay:
            b_val = base[key]
            o_val = overlay[key]
            if isinstance(b_val, dict) and isinstance(o_val, dict):
                result[key] = merge(b_val, o_val)
            else:
                result[key] = copy.deepcopy(o_val)
        elif key in base:
            result[key] = copy.deepcopy(base[key])
        else:
            result[key] = copy.deepcopy(overlay[key])
    return result
