import heapq


def order(deps):
    # Collect all nodes (keys and prerequisite-only nodes)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build in-degree and reverse adjacency
    in_degree = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}

    for node, prereqs in deps.items():
        in_degree[node] = len(prereqs)
        for p in prereqs:
            dependents[p].append(node)

    # Min-heap of currently ready (in-degree 0) nodes
    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
```

